import{_ as e,c as a,o as n,ae as r}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"Rating Element","description":"Rating Element","frontmatter":{"title":"Rating Element","description":"Rating Element"},"headers":[],"relativePath":"guide/drag-drop-elements/star-rating-element-in-ninja-tables-drag-and-drop.md","filePath":"guide/drag-drop-elements/star-rating-element-in-ninja-tables-drag-and-drop.md"}'),o={name:"guide/drag-drop-elements/star-rating-element-in-ninja-tables-drag-and-drop.md"};function i(s,t,l,d,g,u){return n(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="rating-element" tabindex="-1">Rating Element <a class="header-anchor" href="#rating-element" aria-label="Permalink to &quot;Rating Element&quot;">​</a></h1><p>One of the most important things for a business is “Rating” or “Star Rating.” In this document, we will learn about Ninja Tables’ Rating Element. The tiny stars indicate a user&#39;s trust in a product, service, or business. It’s crucial to have a star rating to help visitors realize your product is worth it. Let’s add a Rating element to our Ninja Tables in the drag and drop builder! <img src="https://ninjatables.com/wp-content/uploads/2023/08/Rating-element-in-tables-1024x456.png" alt="Rating element in tables"></p><h2 id="properties-of-rating-element" tabindex="-1"><strong>Properties of Rating Element</strong> <a class="header-anchor" href="#properties-of-rating-element" aria-label="Permalink to &quot;**Properties of Rating Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>Star Size</td><td>Numeric Value, drag bar</td></tr><tr><td>Color</td><td>Graphical Color Selection</td></tr><tr><td>Alignment</td><td>Left, Center, and Right</td></tr><tr><td>Show Rating Value</td><td>Toggle On or Off</td></tr><tr><td>Maximum Star</td><td>Numeric Value, drag bar</td></tr></tbody></table><ul><li>**Star Size: **You can change the size of the star of the Rating element. By default, It is set to 15.</li><li><strong>Color:</strong> You can also change the color of the size of the stars along with the values. By default, It is set to Black.</li><li><strong>Alignment:</strong> You can align the stars to the left, right, or center. By default, it is set to Center.</li><li><strong>Show Rating Value:</strong> You can toggle On or Off to show the value or not. By default, it is set to On.</li><li><strong>Maximum Star:</strong> You can control the maximum number of Stars of the Rating. By default, it is set to 5.</li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>We hope this documentation has helped you understand the functionality of the rating element of Ninja Tables Drag &amp; Drop table builder.  Let us know your thoughts and questions in the comment box.</p>',7)])])}const c=e(o,[["render",i]]);export{m as __pageData,c as default};
